-- rowstile 0.1.0-dev: sync_mirrors. Generated by rowstile migrate from the policy; don't edit it,
-- change the policy and write the next migration.
-- the same policy; what rowstile makes of it changed

-- a migration is one transaction: outside one, nothing below changes anything
SELECT pg_catalog.set_config('authz_ctx.migration', '2d57f7d0c30039d9', true);
DO $authz_tx$
BEGIN
  IF pg_catalog.current_setting('authz_ctx.migration', true) IS DISTINCT FROM '2d57f7d0c30039d9' THEN
    PERFORM pg_catalog.set_config('default_transaction_read_only', 'on', false);
  END IF;
END $authz_tx$;
DO $authz_tx$
BEGIN
  IF pg_catalog.current_setting('authz_ctx.migration', true) IS DISTINCT FROM '2d57f7d0c30039d9' THEN
    RAISE EXCEPTION 'rowstile: this migration must run in one transaction, and its statements are being committed one by one [AZ615]'
      USING HINT = 'nothing was changed, and this session is read-only from here on; run the file with your migration tool, or with psql -1 -f';
  END IF;
END $authz_tx$;

SELECT pg_catalog.set_config('lock_timeout', '10s', true) WHERE pg_catalog.current_setting('lock_timeout') IN ('0', '0ms');
SELECT pg_catalog.set_config('check_function_bodies', 'off', true);

-- this migration starts from the policy the previous one left
DO $authz_guard$
DECLARE v_lock text;
BEGIN
  IF to_regclass('authz.policy_versions') IS NOT NULL THEN
    EXECUTE 'SELECT lock FROM authz.policy_versions ORDER BY id DESC LIMIT 1' INTO v_lock;
  END IF;
  IF v_lock = '2d57f7d0c30039d9' THEN
    RAISE EXCEPTION 'rowstile: this database already holds what this migration brings (it ran here before, or rowstile dev or push took the database there): don''t run it, tell your migration tool it is applied [AZ607]'
      USING HINT = 'Prisma: prisma migrate resolve --applied <the migration''s folder>. Alembic: alembic stamp head. '
                   'Others, and why: rowstile help AZ607';
  ELSIF v_lock IS DISTINCT FROM 'bb4f1a733d778a9d' THEN
    RAISE EXCEPTION 'rowstile: this migration changes the policy the migration before it left (%), but the database has % [AZ607]',
      'bb4f1a733d778a9d', coalesce(v_lock, 'none')
      USING HINT = 'apply the migrations in order; a database changed with rowstile push or apply since needs the '
                   'migrations from the start (or rowstile apply of the policy the previous migration left) '
                   '(rowstile help AZ607)';
  END IF;
END $authz_guard$;

-- The app role must not be the policy's owner, nor a member of it: the rules would not hold for it
DO $ar$
DECLARE v_app name;
BEGIN
  SELECT a.rolname INTO v_app FROM pg_catalog.pg_roles a
  WHERE a.rolname = 'conf_app' AND NOT a.rolsuper AND pg_catalog.pg_has_role(a.oid, CURRENT_USER, 'MEMBER');
  IF v_app IS NOT NULL THEN
    RAISE EXCEPTION 'the app role % is the role that applies the policy (%), or a member of it: the rules would not hold for it [AZ624]', v_app, CURRENT_USER
      USING HINT = 'the policy''s owner skips row-level security, may turn it off, and is believed without a signature: the app connects as a role of its own, which owns nothing of the database';
  END IF;
END $ar$;

-- Functions below resolve names with the search_path in effect now: the schemas that exist, temporary schema last
DO $sp$
DECLARE v_path text; v_bad text; f record;
BEGIN
  SELECT pg_catalog.string_agg(pg_catalog.format('%I (%s)', pw.schema, pw.who), ', ') INTO v_bad FROM (SELECT n.nspname::text AS schema, w.who
FROM pg_catalog.unnest(pg_catalog.current_schemas(false)) s(name) JOIN pg_catalog.pg_namespace n ON n.nspname = s.name,
LATERAL (SELECT CASE WHEN EXISTS (SELECT 1 FROM pg_catalog.aclexplode(n.nspacl) a
                                  WHERE a.grantee = 0 AND a.privilege_type = 'CREATE') THEN 'PUBLIC'
                ELSE (SELECT pg_catalog.string_agg(ro.rolname::text, ', ' ORDER BY ro.rolname) FROM pg_catalog.pg_roles ro
                      WHERE pg_catalog.has_schema_privilege(ro.oid, n.oid, 'CREATE') AND NOT ro.rolsuper
                        AND ro.rolname <> 'pg_database_owner' AND NOT pg_catalog.pg_has_role(ro.oid, CURRENT_USER, 'MEMBER')
                        AND NOT pg_catalog.pg_has_role(ro.oid, (SELECT d.datdba FROM pg_catalog.pg_database d
                                                               WHERE d.datname = pg_catalog.current_database()), 'MEMBER'))
                END AS who) w
-- a temporary schema is the session's own, and never searched for functions or operators
WHERE w.who IS NOT NULL AND n.nspname !~ '^pg_(toast_)?temp_') pw;
  IF v_bad IS NOT NULL THEN
    RAISE EXCEPTION 'the search path has schemas that roles other than the owner may create objects in: % [AZ612]', v_bad
      USING HINT = 'rowstile''s functions that run as the owner resolve names on this path, so a function made there could run as the owner: revoke CREATE on those schemas, or apply with a search path without them';
  END IF;
  SELECT pg_catalog.string_agg(pg_catalog.quote_ident(s.name), ', ' ORDER BY s.i) INTO v_path
  FROM pg_catalog.unnest(pg_catalog.current_schemas(false)) WITH ORDINALITY s(name, i)
  WHERE s.name::text !~ '^pg_temp_';
  PERFORM pg_catalog.set_config('search_path', pg_catalog.concat_ws(', ', v_path, 'pg_temp'), true);
  -- functions made before (a migration keeps those it doesn't change) take the same path
  FOR f IN SELECT p.oid::regprocedure AS fn FROM pg_catalog.pg_proc p
           WHERE p.pronamespace IN (SELECT n.oid FROM pg_catalog.pg_namespace n WHERE n.nspname IN ('authz', 'authz_gen', 'authz_int'))
             AND EXISTS (SELECT 1 FROM pg_catalog.unnest(p.proconfig) c
                         WHERE c ^@ 'search_path=' AND c <> 'search_path=pg_catalog, pg_temp'
                           AND c <> 'search_path=' || pg_catalog.current_setting('search_path')) LOOP
    EXECUTE pg_catalog.format('ALTER FUNCTION %s SET search_path FROM CURRENT', f.fn);
  END LOOP;
END $sp$;

-- The sync index (a preview): who may read each row of the synced tables, as keys, and the keys each principal
-- holds. Kept across applies: the sync engines keep their shapes on these tables
CREATE SCHEMA IF NOT EXISTS authz_sync;
REVOKE ALL ON SCHEMA authz_sync FROM PUBLIC;
-- tables this policy doesn't keep, and a readers table whose key columns are not the type's any more, go
DO $sb$
DECLARE r record;
BEGIN
  FOR r IN SELECT c.oid::regclass AS tbl FROM pg_catalog.pg_class c
           LEFT JOIN (VALUES ('keys', ARRAY['principal_type', 'principal_id', 'key']::name[], ARRAY['text', 'text', 'text']::regtype[]),
             ('groups', ARRAY['grp', 'key']::name[], ARRAY['text', 'text']::regtype[]),
             ('expanded', ARRAY['object_type', 'object_id', 'key']::name[], ARRAY['text', 'text', 'text']::regtype[]),
             ('definitions', ARRAY['name', 'hash']::name[], ARRAY['text', 'text']::regtype[]),
             ('file__readers', ARRAY['id', 'key']::name[], ARRAY['integer', 'text']::regtype[]),
             ('folder__readers', ARRAY['id', 'key']::name[], ARRAY['integer', 'text']::regtype[]),
             ('note__readers', ARRAY['id', 'key']::name[], ARRAY['integer', 'text']::regtype[])) w(name, cols, types) ON w.name = c.relname
           WHERE c.relnamespace = 'authz_sync'::regnamespace AND c.relkind IN ('r', 'p')
             AND (w.name IS NULL
                  OR w.cols IS NOT NULL AND (
                    (SELECT array_agg(a.attname ORDER BY a.attnum) FROM pg_catalog.pg_attribute a
                     WHERE a.attrelid = c.oid AND a.attnum > 0 AND NOT a.attisdropped) IS DISTINCT FROM w.cols
                    OR (SELECT array_agg(a.atttypid::regtype ORDER BY a.attnum) FROM pg_catalog.pg_attribute a
                        WHERE a.attrelid = c.oid AND a.attnum > 0 AND NOT a.attisdropped) IS DISTINCT FROM w.types)) LOOP
    EXECUTE format('DROP TABLE %s', r.tbl);
  END LOOP;
  -- a table missing (dropped since, or just now): what the index holds is worked out again (sync_refresh)
  IF to_regclass('authz_sync.definitions') IS NOT NULL AND EXISTS (
       SELECT 1 FROM (VALUES ('keys', ARRAY['principal_type', 'principal_id', 'key']::name[], ARRAY['text', 'text', 'text']::regtype[]),
             ('groups', ARRAY['grp', 'key']::name[], ARRAY['text', 'text']::regtype[]),
             ('expanded', ARRAY['object_type', 'object_id', 'key']::name[], ARRAY['text', 'text', 'text']::regtype[]),
             ('definitions', ARRAY['name', 'hash']::name[], ARRAY['text', 'text']::regtype[]),
             ('file__readers', ARRAY['id', 'key']::name[], ARRAY['integer', 'text']::regtype[]),
             ('folder__readers', ARRAY['id', 'key']::name[], ARRAY['integer', 'text']::regtype[]),
             ('note__readers', ARRAY['id', 'key']::name[], ARRAY['integer', 'text']::regtype[])) w(name, cols, types)
       WHERE w.cols IS NOT NULL AND to_regclass(pg_catalog.format('authz_sync.%I', w.name)) IS NULL) THEN
    DELETE FROM authz_sync.definitions;
  END IF;
END $sb$;
-- the keys each principal holds: its own (user:42), every one of its type's (user:*), anyone's, and its groups'
CREATE TABLE IF NOT EXISTS authz_sync.keys (principal_type text NOT NULL, principal_id text NOT NULL, key text NOT NULL,
  PRIMARY KEY (principal_type, principal_id, key));
CREATE INDEX IF NOT EXISTS keys_by_key ON authz_sync.keys (key);
ALTER TABLE authz_sync.keys REPLICA IDENTITY FULL;
-- the keys that make up each group key (team#member:10): a principal holding one holds the group's
CREATE TABLE IF NOT EXISTS authz_sync.groups (grp text NOT NULL, key text NOT NULL, PRIMARY KEY (grp, key));
CREATE INDEX IF NOT EXISTS groups_by_key ON authz_sync.groups (key);
ALTER TABLE authz_sync.groups REPLICA IDENTITY FULL;
-- the keys a row's readers were worked out from, where they are principals (an and / not between groups)
CREATE TABLE IF NOT EXISTS authz_sync.expanded (object_type text NOT NULL, object_id text NOT NULL, key text NOT NULL,
  PRIMARY KEY (object_type, object_id, key));
CREATE INDEX IF NOT EXISTS expanded_by_key ON authz_sync.expanded (key);
ALTER TABLE authz_sync.expanded REPLICA IDENTITY FULL;
-- what the rows were worked out by: an apply that changes it works them out again (by difference)
CREATE TABLE IF NOT EXISTS authz_sync.definitions (name text PRIMARY KEY, hash text NOT NULL);
ALTER TABLE authz_sync.definitions REPLICA IDENTITY FULL;
CREATE TABLE IF NOT EXISTS authz_sync."file__readers" ("id" integer NOT NULL, key text NOT NULL, PRIMARY KEY ("id", key));
CREATE INDEX IF NOT EXISTS "file__readers_key" ON authz_sync."file__readers" (key);
ALTER TABLE authz_sync."file__readers" REPLICA IDENTITY FULL;
CREATE TABLE IF NOT EXISTS authz_sync."folder__readers" ("id" integer NOT NULL, key text NOT NULL, PRIMARY KEY ("id", key));
CREATE INDEX IF NOT EXISTS "folder__readers_key" ON authz_sync."folder__readers" (key);
ALTER TABLE authz_sync."folder__readers" REPLICA IDENTITY FULL;
CREATE TABLE IF NOT EXISTS authz_sync."note__readers" ("id" integer NOT NULL, key text NOT NULL, PRIMARY KEY ("id", key));
CREATE INDEX IF NOT EXISTS "note__readers_key" ON authz_sync."note__readers" (key);
ALTER TABLE authz_sync."note__readers" REPLICA IDENTITY FULL;
REVOKE ALL ON ALL TABLES IN SCHEMA authz_sync FROM PUBLIC;

-- The partitions of a table rowstile watches and the tables that inherit from it: the triggers made above, on
-- each, for the rows stored there and the statements on it
DO $ch$
DECLARE r record;
BEGIN
  FOR r IN SELECT * FROM authz_int.child_triggers() LOOP
    EXECUTE r.stmt;
    EXECUTE pg_catalog.format('COMMENT ON TRIGGER %I ON %s IS %L', r.name, r.child, 'rowstile: the trigger of the table above, for the rows stored here');
  END LOOP;
END $ch$;

-- The sync role reads the index, and nothing else rowstile keeps
DO $sr$
DECLARE v_sync oid := to_regrole('"conf_zero"'); v_app oid := to_regrole('"conf_app"'); v_cols text;
BEGIN
  IF v_sync IS NULL THEN
    RAISE EXCEPTION 'the sync role conf_zero does not exist [AZ808]'
      USING HINT = 'make it for the engine: CREATE ROLE conf_zero LOGIN REPLICATION BYPASSRLS, then apply again';
  END IF;
  IF pg_catalog.pg_has_role(v_sync, CURRENT_USER, 'MEMBER') THEN
    RAISE EXCEPTION 'the sync role conf_zero is the role that applies the policy (%), or a member of it [AZ808]', CURRENT_USER
      USING HINT = 'the engine connects as a role of its own, which owns nothing of the database';
  END IF;
  IF v_app IS NOT NULL AND (pg_catalog.pg_has_role(v_sync, v_app, 'MEMBER') OR pg_catalog.pg_has_role(v_app, v_sync, 'MEMBER')) THEN
    RAISE EXCEPTION 'the sync role conf_zero and the app role conf_app are one another''s members: the app would read every row [AZ808]'
      USING HINT = 'the engine connects as a role of its own, which the app role is not a member of, nor it of the app role';
  END IF;
  SELECT pg_catalog.string_agg(m.tbl || '.' || m.col, ', ' ORDER BY m.tbl, m.col) INTO v_cols FROM authz_int.masked_columns m
  WHERE pg_catalog.has_column_privilege(v_sync, m.tbl, m.col, 'SELECT');
  IF v_cols IS NOT NULL THEN
    RAISE EXCEPTION 'the sync role conf_zero may read masked columns: % [AZ809]', v_cols
      USING HINT = 'it reads every row, so a masked column would reach every client: revoke SELECT on the table, grant the other columns (GRANT SELECT (id, name) ON ...), then apply again';
  END IF;
END $sr$;
GRANT USAGE ON SCHEMA authz_sync TO "conf_zero";
GRANT SELECT ON ALL TABLES IN SCHEMA authz_sync TO "conf_zero";

-- Privileges the policy doesn't give on rowstile's schemas and what is in them are taken back
DO $r$
DECLARE g record; v_taken int := 0;
BEGIN
  FOR g IN SELECT n.nspname::text AS object, gw.who, a.privilege_type AS privilege,
       format('REVOKE %s ON SCHEMA %I FROM %s CASCADE', a.privilege_type, n.nspname, gw.who) AS stmt
  FROM pg_namespace n, aclexplode(n.nspacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE n.nspname IN ('authz', 'authz_gen', 'authz_int') AND a.grantee <> n.nspowner
    AND NOT (a.grantee = '"conf_app"'::regrole AND n.nspname <> 'authz_int' AND a.privilege_type = 'USAGE')
UNION ALL
SELECT c.oid::regclass::text, gw.who, a.privilege_type,
       format('REVOKE %s ON %s %s FROM %s CASCADE', a.privilege_type, CASE c.relkind WHEN 'S' THEN 'SEQUENCE' ELSE 'TABLE' END,
              c.oid::regclass, gw.who)
  FROM pg_class c, aclexplode(c.relacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE c.relnamespace IN (SELECT oid FROM pg_namespace WHERE nspname IN ('authz', 'authz_gen', 'authz_int')) AND a.grantee <> c.relowner
    AND NOT (a.grantee = '"conf_app"'::regrole AND a.privilege_type = 'SELECT'
             AND c.relnamespace::regnamespace::text || '."' || replace(c.relname, '"', '""') || '"' = ANY (ARRAY['authz_gen."policy_lines"', 'authz_int."file__view"', 'authz_int."file__viewer"', 'authz_int."folder__edit"', 'authz_int."folder__edit__direct"', 'authz_int."folder__team"', 'authz_int."folder__view"', 'authz_int."folder__viewer"']::text[]))
UNION ALL
SELECT format('%s (%I)', c.oid::regclass, att.attname), gw.who, a.privilege_type,
       format('REVOKE %s (%I) ON %s FROM %s CASCADE', a.privilege_type, att.attname, c.oid::regclass, gw.who)
  FROM pg_class c JOIN pg_attribute att ON att.attrelid = c.oid, aclexplode(att.attacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE c.relnamespace IN (SELECT oid FROM pg_namespace WHERE nspname IN ('authz', 'authz_gen', 'authz_int')) AND att.attacl IS NOT NULL
UNION ALL
SELECT p.oid::regprocedure::text, gw.who, a.privilege_type,
       format('REVOKE %s ON ROUTINE %s FROM %s CASCADE', a.privilege_type, p.oid::regprocedure, gw.who)
  FROM pg_proc p, aclexplode(p.proacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE p.pronamespace IN (SELECT oid FROM pg_namespace WHERE nspname IN ('authz', 'authz_gen', 'authz_int')) AND a.grantee <> p.proowner
    AND NOT (p.pronamespace = 'authz_int'::regnamespace AND a.grantee IN (0, '"conf_app"'::regrole))
    AND NOT (p.pronamespace = 'authz_gen'::regnamespace AND a.grantee = '"conf_app"'::regrole
             AND '"' || replace(p.proname, '"', '""') || '"' = ANY (ARRAY['"app.files:column owner_id:items"', '"app.files:column owner_id:why"', '"app.files:insert:items"', '"app.files:insert:refuse"', '"app.files:insert:why"', '"app.files:rules:explain"', '"app.files:update:items"', '"app.files:update:refuse"', '"app.files:update:why"', '"app.folders:column parent_id after:items"', '"app.folders:column parent_id after:why"', '"app.folders:rules:explain"', '"app.folders:update:items"', '"app.folders:update:refuse"', '"app.folders:update:why"', '"app.notes:rules:explain"']::text[]))
    AND NOT (p.pronamespace = 'authz'::regnamespace AND a.grantee = '"conf_app"'::regrole AND p.oid = ANY (ARRAY['authz.uid()', 'authz.principal()', 'authz.ctx(text)', 'authz.link_hashes()', 'authz.act_as(text, text)', 'authz.connection_check()', 'authz.session_limited()', 'authz.can(text, text, text)', 'authz.list(text, text, text, integer)', 'authz.perms(text, text)', 'authz.perms_of(text, text[])', 'authz.share(text, text, text, text, text, text, timestamptz, timestamptz, text, jsonb)', 'authz.unshare(text, text, text, text, text, text)', 'authz.create_link(text, text, text, timestamptz)', 'authz.list_links(text, text)', 'authz.revoke_link(text, text, text)', 'authz.create_role(text, text, text, text, text[])', 'authz.set_role_permissions(bigint, text[])', 'authz.delete_role(bigint)', 'authz.roles_of(text, text)', 'authz.who(text, text, text)', 'authz.explain(text, text, text, text)', 'authz.list_shares(text, text)', 'authz.explain_rule(text, text, text, jsonb)', 'authz.who_among(text, text, text, text[], text)', 'authz.create_api_key(text, text, timestamptz, text, text)', 'authz.list_api_keys(text, text)', 'authz.revoke_api_key(bigint)', 'authz.login_key(text)', 'authz.login_jwt(text)', 'authz.view_as(text, text)', 'authz.request_access(text, text, text, text, interval)', 'authz.pending_requests()', 'authz.decide_request(bigint, boolean, text)', 'authz.cancel_request(bigint)', 'authz.break_glass(text, text, text, text, interval)', 'authz.start_review(text, text, timestamptz)', 'authz.review_items(bigint)', 'authz.review_decide(bigint, integer, boolean)', 'authz.close_review(bigint, boolean)', 'authz.who(text, integer, text)', 'authz.explain(text, integer, text, text)', 'authz.list_shares(text, integer)', 'authz.list_links(text, integer)', 'authz.revoke_link(text, integer, text)', 'authz.create_link(text, integer, text, timestamptz)', 'authz.create_role(text, integer, text, text, text[])', 'authz.roles_of(text, integer)', 'authz.request_access(text, integer, text, text, interval)', 'authz.break_glass(text, integer, text, text, interval)', 'authz.start_review(text, integer, timestamptz)', 'authz.can(text, integer, text)', 'authz.who_among(text, integer, text, text[], text)', 'authz.perms(text, integer)', 'authz.share(text, text, text, text, integer, text, timestamptz, timestamptz, text, jsonb)', 'authz.unshare(text, text, text, text, integer, text)', 'authz.share(text, integer, text, text, text, text, timestamptz, timestamptz, text, jsonb)', 'authz.unshare(text, integer, text, text, text, text)', 'authz.share(text, integer, text, text, integer, text, timestamptz, timestamptz, text, jsonb)', 'authz.unshare(text, integer, text, text, integer, text)']::regprocedure[]))
UNION ALL
SELECT n.nspname::text, gw.who, a.privilege_type,
       format('REVOKE %s ON SCHEMA %I FROM %s CASCADE', a.privilege_type, n.nspname, gw.who)
  FROM pg_namespace n, aclexplode(n.nspacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE n.nspname = 'authz_sync' AND a.grantee <> n.nspowner
    AND NOT (a.grantee = to_regrole('"conf_zero"') AND a.privilege_type = 'USAGE')
UNION ALL
SELECT c.oid::regclass::text, gw.who, a.privilege_type,
       format('REVOKE %s ON TABLE %s FROM %s CASCADE', a.privilege_type, c.oid::regclass, gw.who)
  FROM pg_class c, aclexplode(c.relacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE c.relnamespace = 'authz_sync'::regnamespace AND a.grantee <> c.relowner
    AND NOT (a.grantee = to_regrole('"conf_zero"') AND a.privilege_type = 'SELECT')
UNION ALL
SELECT format('%s (%I)', c.oid::regclass, att.attname), gw.who, a.privilege_type,
       format('REVOKE %s (%I) ON %s FROM %s CASCADE', a.privilege_type, att.attname, c.oid::regclass, gw.who)
  FROM pg_class c JOIN pg_attribute att ON att.attrelid = c.oid, aclexplode(att.attacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE c.relnamespace = 'authz_sync'::regnamespace AND att.attacl IS NOT NULL LOOP
    EXECUTE g.stmt;
    v_taken := v_taken + 1;
  END LOOP;
  IF v_taken > 0 THEN
    RAISE WARNING 'took back % privileges on rowstile''s schemas that the policy doesn''t give (default privileges of the owner, or grants made since the last apply)', v_taken;
  END IF;
END $r$;

REVOKE ALL ON ALL FUNCTIONS IN SCHEMA authz FROM PUBLIC;

GRANT USAGE ON SCHEMA authz, authz_gen TO "conf_app";

REVOKE ALL ON ALL FUNCTIONS IN SCHEMA authz_gen FROM PUBLIC;

-- Tables never analyzed (made just now, or too small for autovacuum to have reached them) are planned
-- as ten pages of rows: a table of 6 rows as thousands. Through the rules' lookups that becomes an estimate of
-- hundreds of thousands, and Postgres compiles (JIT) and plans for reads of a few rows. ANALYZE reads a
-- sample (30,000 rows at most) and blocks neither reads nor writes.
DO $an$
DECLARE r record;
BEGIN
  FOR r IN SELECT c.oid::regclass AS tbl FROM pg_class c
           WHERE c.relkind = 'r' AND c.relpersistence <> 't' AND c.reltuples < 0
             AND pg_has_role(c.relowner, 'USAGE')
             AND (c.relnamespace IN (SELECT oid FROM pg_namespace WHERE nspname IN ('authz', 'authz_int', 'authz_sync'))
                  OR c.oid = ANY (SELECT to_regclass(x) FROM unnest(ARRAY['"app"."users"', '"app"."teams"', '"app"."team_members"', '"app"."folders"', '"app"."folder_teams"', '"app"."files"', '"app"."notes"']::text[]) x)) LOOP
    EXECUTE format('ANALYZE %s', r.tbl);
  END LOOP;
END $an$;

-- the policy now in force
INSERT INTO authz.policy_versions (action, policy, files, version, lock)
VALUES ('apply', $authz_policy$-- The Zero suite's policy (the Electric suite's): folders inside folders, given to teams (and the teams inside
-- them), files in folders, shares on both, a confidential flag that keeps a file from those who read it only through
-- its folder, and notes on files whose body only their editors read. Zero syncs the files, the folders and the
-- notes; the sync index keeps who may read each row (sync lines), and the app's query endpoint adds each table's
-- filter to the ZQL it gives zero-cache.

app role conf_app
sync role conf_zero

type user = app.users(id integer)

type team = app.teams(id integer)
  member : user        = app.team_members(team_id -> user_id)
  member : team#member = app.teams(parent_id -> id)  -- the members of the teams inside it

type folder = app.folders(id integer)
  parent : folder      = parent_id
  owner  : user        = owner_id
  team   : team#member = app.folder_teams(folder_id -> team_id)
  viewer : user shared by edit

  can edit = owner or parent.edit
  can view = edit or team or viewer or parent.view

type file = app.files(id integer)
  folder : folder = folder_id
  owner  : user   = owner_id
  viewer : user shared by edit

  can edit = owner or folder.edit
  can view = edit or viewer or (folder.view and not {confidential})

type note = app.notes(id integer)
  file   : file = file_id
  author : user = author_id

  can edit = author or file.edit
  can view = file.view

rules app.folders
  select                 : view
  update                 : edit
  update parent_id after : parent.edit

rules app.files
  select          : view
  insert          : folder.edit and owner
  update          : edit
  update owner_id : nobody

rules app.notes view app.notes_visible
  select    : view
  mask body : edit

sync app.files : view
sync app.folders
sync app.notes
$authz_policy$,
  $authz_files${}$authz_files$::jsonb, '0.1.0-dev+8eafc5fbe16d', '2d57f7d0c30039d9');
